//autogenerated:yes
//nolint:revive,govet,errcheck
package common_test

import (
	"testing"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/common"
	"github.com/stretchr/testify/require"
)

func TestEnum_ACTUATOR_CONFIGURATION(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.ACTUATOR_CONFIGURATION
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.ACTUATOR_CONFIGURATION_NONE.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.ACTUATOR_CONFIGURATION
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.ACTUATOR_CONFIGURATION_NONE, dec)
	})
}
